    /**
     * Tests getting all Suppliers.
     *
     * @return    Collection
     */
    public List<Supplier> testGetAll() throws Throwable {
    LOGGER.info( "SupplierTest:testGetAll() - Retrieving Collection of Suppliers:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Supplier : " );
    List<Supplier> collection  = null;

    try {
        // call the static get method on the SupplierService
        collection = service.getAllSupplier();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Supplier currEntity  = null;
            Iterator<Supplier> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getSupplierId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

